const body = $input.first().json.body ?? {};
const question = String(body.question ?? '').trim();
const askedBy = String(body.asked_by ?? '').slice(0, 254);
const supplied = Array.isArray(body.schemas) ? body.schemas : [];
const ident = /^[a-z][a-z0-9_]{0,62}$/;

if (!question) return [{json:{valid:false,statusCode:400,error:'Missing question'}}];
if (question.length > 2000) return [{json:{valid:false,statusCode:400,error:'Question is too long (maximum 2,000 characters)'}}];
if (!supplied.length) return [{json:{valid:false,statusCode:422,error:'No searchable datasets are available'}}];

const schemas = supplied.filter(s => s && ident.test(String(s.table ?? '')) && Array.isArray(s.columns)).map(s => ({
  table: String(s.table),
  label: String(s.label ?? s.table).slice(0,150),
  description: String(s.description ?? '').slice(0,500),
  row_count: Math.max(0, Number(s.row_count ?? 0)),
  columns: s.columns.filter(c => c && ident.test(String(c.name ?? ''))).map(c => ({
    name: String(c.name),
    type: String(c.type ?? 'TEXT').slice(0,100),
    label: String(c.label ?? c.name).slice(0,100),
    description: String(c.description ?? '').slice(0,300),
    values: Array.isArray(c.values) ? c.values.slice(0,100).map(v => String(v).slice(0,200)) : []
  }))
})).filter(s => s.columns.length);

if (!schemas.length) return [{json:{valid:false,statusCode:422,error:'No valid searchable schemas were supplied'}}];

const schemaText = schemas.map(s => {
  const cols = s.columns.map(c => {
    let line = `- ${c.name} (${c.type})`;
    if (c.label !== c.name) line += `; label: ${c.label}`;
    if (c.description) line += `; ${c.description}`;
    if (c.values.length) line += `; known values: ${c.values.join(' | ')}`;
    return line;
  }).join('\n');
  let rules = '';
  if (s.table === 'leads') rules = '\nSPECIAL RULES FOR leads:\n- sectors_norm is a comma-separated exact vocabulary. Use operator contains_any with one or more exact sector values.\n- primary_sector is only the main trade.\n- has_email stores Yes or No as strings.\n- phone_type normally stores mobile, fixed line, voip, or other.\n- contact_person may contain multiple people in one field.\n- Empty values may be either NULL or an empty string.';
  return `TABLE: ${s.table}\nDISPLAY NAME: ${s.label}\nDESCRIPTION: ${s.description || 'No description provided'}\nAPPROXIMATE ROWS: ${s.row_count}\nCOLUMNS:\n${cols}${rules}`;
}).join('\n\n');

return [{json:{valid:true,question,asked_by:askedBy,schemas,schema_text:schemaText}}];

const source = $('Prepare Dynamic Schema').first().json;
const item = $input.first().json;
const raw = item.text ?? item.output ?? item.message?.content ?? item.choices?.[0]?.message?.content ?? '';
let plan;
try { plan = JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim()); }
catch { return [{json:{valid:false,statusCode:502,error:'The AI returned invalid JSON'}}]; }
if (plan.answerable === false) return [{json:{valid:false,no_query:true,statusCode:422,error:String(plan.explanation || 'This question cannot be answered from the searchable datasets.')}}];

const intents = new Set(['list','count','aggregate']);
const operators = new Set(['equals','not_equals','contains','contains_any','starts_with','ends_with','is_empty','is_not_empty','greater_than','greater_or_equal','less_than','less_or_equal','between','in']);
if (!intents.has(plan.intent)) return [{json:{valid:false,statusCode:422,error:'The AI selected an invalid query intent'}}];
const schema = source.schemas.find(s => s.table === plan.table);
if (!schema) return [{json:{valid:false,statusCode:422,error:'The AI selected an unavailable dataset'}}];
const allowed = new Set(schema.columns.map(c => c.name));
const columns = Array.isArray(plan.columns) ? plan.columns : [];
const filters = Array.isArray(plan.filters) ? plan.filters : [];
const groupBy = Array.isArray(plan.group_by) ? plan.group_by : [];
const orderBy = Array.isArray(plan.order_by) ? plan.order_by : [];
for (const c of [...columns,...groupBy]) if (!allowed.has(c)) return [{json:{valid:false,statusCode:422,error:`Unknown column selected: ${c}`}}];
for (const o of orderBy) if (!allowed.has(o.column) || !['asc','desc'].includes(String(o.direction).toLowerCase())) return [{json:{valid:false,statusCode:422,error:'Invalid ordering requested'}}];
for (const f of filters) {
  if (!allowed.has(f.column)) return [{json:{valid:false,statusCode:422,error:`Unknown filter column: ${f.column}`}}];
  if (!operators.has(f.operator)) return [{json:{valid:false,statusCode:422,error:`Invalid filter operator: ${f.operator}`}}];
  if (f.operator === 'between' && (!Array.isArray(f.value) || f.value.length !== 2)) return [{json:{valid:false,statusCode:422,error:'Between requires exactly two values'}}];
  if (['in','contains_any'].includes(f.operator) && (!Array.isArray(f.value) || !f.value.length || f.value.length > 50)) return [{json:{valid:false,statusCode:422,error:`${f.operator} requires an array of 1-50 values`}}];
  if (f.operator === 'contains_any' && f.column !== 'sectors_norm') return [{json:{valid:false,statusCode:422,error:'contains_any is not allowed for this column'}}];
}
if (plan.intent === 'aggregate' && !groupBy.length) return [{json:{valid:false,statusCode:422,error:'An aggregate query requires group_by'}}];

const qi = n => '`' + n + '`';
const esc = v => {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return "'" + String(v).replace(/\\/g,'\\\\').replace(/'/g,"''").replace(/\u0000/g,'') + "'";
};
const where = [];
for (const f of filters) {
  const c = qi(f.column);
  switch (f.operator) {
    case 'equals': where.push(`${c} = ${esc(f.value)}`); break;
    case 'not_equals': where.push(`${c} <> ${esc(f.value)}`); break;
    case 'contains': where.push(`LOWER(${c}) LIKE LOWER(${esc('%' + String(f.value) + '%')})`); break;
    case 'starts_with': where.push(`LOWER(${c}) LIKE LOWER(${esc(String(f.value) + '%')})`); break;
    case 'ends_with': where.push(`LOWER(${c}) LIKE LOWER(${esc('%' + String(f.value))})`); break;
    case 'is_empty': where.push(`(${c} IS NULL OR ${c} = '')`); break;
    case 'is_not_empty': where.push(`(${c} IS NOT NULL AND ${c} <> '')`); break;
    case 'greater_than': where.push(`${c} > ${esc(f.value)}`); break;
    case 'greater_or_equal': where.push(`${c} >= ${esc(f.value)}`); break;
    case 'less_than': where.push(`${c} < ${esc(f.value)}`); break;
    case 'less_or_equal': where.push(`${c} <= ${esc(f.value)}`); break;
    case 'between': where.push(`${c} BETWEEN ${esc(f.value[0])} AND ${esc(f.value[1])}`); break;
    case 'in': where.push(`${c} IN (${f.value.map(esc).join(', ')})`); break;
    case 'contains_any': where.push('(' + f.value.map(v => `FIND_IN_SET(${esc(v)}, ${c})`).join(' OR ') + ')'); break;
  }
}
let sql;
let outputColumns;
if (plan.intent === 'count') {
  outputColumns = ['total'];
  sql = `SELECT COUNT(*) AS total FROM ${qi(schema.table)}`;
} else if (plan.intent === 'aggregate') {
  outputColumns = [...groupBy,'total'];
  sql = `SELECT ${groupBy.map(qi).join(', ')}, COUNT(*) AS total FROM ${qi(schema.table)}`;
} else {
  outputColumns = columns.length ? columns : schema.columns.slice(0,6).map(c => c.name);
  sql = `SELECT ${outputColumns.map(qi).join(', ')} FROM ${qi(schema.table)}`;
}
if (where.length) sql += ' WHERE ' + where.join(' AND ');
if (plan.intent === 'aggregate') {
  sql += ' GROUP BY ' + groupBy.map(qi).join(', ');
  sql += ' ORDER BY total DESC';
  sql += ' LIMIT 100';
} else if (plan.intent === 'list') {
  if (orderBy.length) sql += ' ORDER BY ' + orderBy.map(o => `${qi(o.column)} ${String(o.direction).toUpperCase()}`).join(', ');
  sql += ` LIMIT ${Math.min(Math.max(Number(plan.limit) || 250,1),250)}`;
}
return [{json:{valid:true,sql,question:source.question,asked_by:source.asked_by,dataset:schema.table,dataset_label:schema.label,intent:plan.intent,columns:outputColumns,explanation:String(plan.explanation || ''),confidence:['high','medium','low'].includes(plan.confidence) ? plan.confidence : 'low'}}];

const plan = $('Validate Plan and Build SQL').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && !r.error);
return [{json:{success:true,question:plan.question,sql:plan.sql,explanation:plan.explanation,confidence:plan.confidence,intent:plan.intent,dataset:plan.dataset,dataset_label:plan.dataset_label,row_count:rows.length,found:rows.length > 0,message:rows.length ? null : 'No records matched that search.',data:rows}}];

const incoming = $input.first().json;
const detail = incoming.error?.message ?? incoming.message ?? incoming.error ?? 'Database query failed';
return [{json:{success:false,error:'The database query failed.',detail:String(detail).slice(0,500)}}];
